// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Img, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading
const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: montserratFamily } = loadMontserrat();



export type CinematicGlassMeetingProps = Record<string, any>;

const CinematicGlassMeeting: React.FC<CinematicGlassMeetingProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  backgroundImage = "https://images.unsplash.com/photo-1556761175-4b46a572b786?auto=format&fit=crop&q=80&w=1920&h=1080",
  title = "EXECUTIVE BRIEFING",
  subtitle = "Malloy Studio",
  reflectionIntensity = 0.65,
  cinematicTint = "#021226",
  focusPullDelay = 1.5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // Background color logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation: Slow, deliberate camera push (zoom in)
  const bgScale = interpolate(
    frame,
    [0, durationInFrames],
    [1.02, 1.15],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Animation: Focus Pull (blur simulating looking through glass, then focusing on subjects)
  const focusPullStartFrame = focusPullDelay * fps;
  const focusPullEndFrame = focusPullStartFrame + (fps * 2); // 2 second focus pull
  const bgBlur = interpolate(
    frame,
    [0, focusPullStartFrame, focusPullEndFrame],
    [12, 12, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Animation: Glass reflections panning across the screen
  const reflectionPan1 = interpolate(
    frame,
    [0, durationInFrames],
    [-width, width * 1.5],
    { extrapolateRight: "clamp" }
  );
  
  const reflectionPan2 = interpolate(
    frame,
    [0, durationInFrames],
    [width * 1.5, -width * 0.5],
    { extrapolateRight: "clamp" }
  );

  // Text Entrance
  const textRevealStartFrame = focusPullEndFrame - (fps * 0.5);
  const textOpacity = interpolate(
    frame,
    [textRevealStartFrame, textRevealStartFrame + fps],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  
  const textY = interpolate(
    frame,
    [textRevealStartFrame, textRevealStartFrame + (fps * 1.5)],
    [40, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const titleSpacing = interpolate(
    frame,
    [textRevealStartFrame, durationInFrames],
    [0.1, 0.3],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* 1. Base Image Layer with Scale and Blur */}
      <AbsoluteFill
        style={{
          transform: `scale(${bgScale})`,
          filter: `blur(${bgBlur}px)`,
          transition: "none",
        }}
      >
        <Img
          src={backgroundImage}
          style={{ width: "100%", height: "100%", objectFit: "cover" }}
        />
        {/* Cinematic Color Wash / Tint */}
        <AbsoluteFill
          style={{
            backgroundColor: cinematicTint,
            opacity: 0.45,
            mixBlendMode: "color",
          }}
        />
        {/* Contrast Darken for legibility and mood */}
        <AbsoluteFill
          style={{
            backgroundColor: "#000",
            opacity: 0.25,
          }}
        />
      </AbsoluteFill>

      {/* 2. Glass Reflection Layers */}
      {/* Primary sharp reflection moving right */}
      <AbsoluteFill
        style={{
          background: `linear-gradient(105deg, transparent 40%, rgba(255,255,255,${reflectionIntensity * 0.7}) 45%, rgba(255,255,255,${reflectionIntensity}) 50%, transparent 55%)`,
          transform: `translateX(${reflectionPan1}px)`,
          mixBlendMode: "overlay",
          opacity: 0.8,
          transition: "none",
        }}
      />
      
      {/* Secondary softer reflection moving left */}
      <AbsoluteFill
        style={{
          background: `linear-gradient(75deg, transparent 30%, rgba(255,255,255,${reflectionIntensity * 0.3}) 50%, transparent 70%)`,
          transform: `translateX(${reflectionPan2}px)`,
          mixBlendMode: "soft-light",
          transition: "none",
        }}
      />

      {/* Subtle Light Leak simulating environment behind camera */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse at ${interpolate(frame, [0, durationInFrames], [20, 80])}% -20%, rgba(150, 200, 255, 0.15) 0%, transparent 60%)`,
          mixBlendMode: "screen",
          transition: "none",
        }}
      />

      {/* 3. Cinematic Vignette */}
      <AbsoluteFill
        style={{
          background: "radial-gradient(circle at 50% 50%, transparent 40%, rgba(0,0,0,0.85) 120%)",
        }}
      />

      {/* 4. Foreground Typography Content */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          opacity: textOpacity,
          transform: `translateY(${textY}px)`,
          transition: "none",
        }}
      >
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", width: width * 0.8 }}>
          <h2
            style={{
              fontFamily: montserratFamily,
              fontWeight: 300,
              fontSize: 28,
              letterSpacing: `${titleSpacing + 0.2}em`,
              color: "rgba(255,255,255,0.7)",
              textTransform: "uppercase",
              margin: 0,
              marginBottom: 16,
              textShadow: "0px 4px 12px rgba(0,0,0,0.5)",
              textAlign: "center",
            }}
          >
            {subtitle}
          </h2>
          <h1
            style={{
              fontFamily: playfairFamily,
              fontWeight: 600,
              fontSize: 84,
              letterSpacing: `${titleSpacing}em`,
              color: "#ffffff",
              textTransform: "uppercase",
              margin: 0,
              textAlign: "center",
              lineHeight: 1.1,
              textShadow: "0px 10px 30px rgba(0,0,0,0.8)",
            }}
          >
            {title}
          </h1>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CinematicGlassMeeting;